#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Set up the print server (Cloudflare Tunnel, Access, services) or one printer device.
# Every stage checks what already exists, so a re-run keeps tokens and settings.

usage() {
  cat <<'EOF'
Usage: deploy/wizard.sh <role>

  server   on the server machine: config, server service, Cloudflare Tunnel and Access
  device   on each printer machine: printer token and device service
  tokens   on the server machine: show a printer's token, to paste into its device
EOF
}

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
export REPO
OS=$(uname -s)
SERVICE_USER=$(id -un)
HOME_DIR=$HOME
SERVER_LABEL=com.daily-printer.server
DEVICE_LABEL=com.daily-printer.device
CLOUDFLARED_LABEL=com.cloudflare.cloudflared
CLOUDFLARED_CONFIG=/etc/cloudflared/config.yml
DOCS=https://developers.cloudflare.com/cloudflare-one
PLACEHOLDERS="SERVICE_USER UV REPO CONFIG HOME_DIR LOG_DIR SERVER_URL TOKEN_FILE TUNNEL_ID DEVICE_HOST SENDER_HOST PORT"
HOSTNAME_PATTERN='^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$'
UV=""

die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET" >&2; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# render TEMPLATE prints it with each __NAME__ replaced by the shell variable NAME.
render() {
  local text name
  text=$(<"$1")
  for name in $PLACEHOLDERS; do
    if [[ "$text" == *"__${name}__"* && -z "${!name-}" ]]; then die "$1: no value for __${name}__"; fi
    text=${text//__${name}__/"${!name-}"}
  done
  if [[ "$text" =~ __[A-Z_]+__ ]]; then die "$1: unknown placeholder ${BASH_REMATCH[0]}"; fi
  printf '%s\n' "$text"
}

# install_rendered TEMPLATE DEST MODE [sudo]
install_rendered() {
  local temp; temp=$(mktemp)
  render "$1" > "$temp"
  ${4:-} install -m "$3" "$temp" "$2"
  rm -f "$temp"
  ok "installed $2"
}

# wait_for_status URL CODE SECONDS: true once URL answers with HTTP CODE.
wait_for_status() {
  local deadline=$((SECONDS + $3)) code=""
  while (( SECONDS < deadline )); do
    code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 5 "$1" || true)
    [[ "$code" == "$2" ]] && return 0
    sleep 2
  done
  LAST_STATUS=$code
  return 1
}

# launchd_load DOMAIN PLIST LABEL [sudo]: (re)loads a job.
launchd_load() {
  ${4:-} launchctl bootout "$1/$3" 2>/dev/null || true
  for _ in 1 2 3 4 5; do
    ${4:-} launchctl bootstrap "$1" "$2" 2>/dev/null && { ok "loaded $3"; return 0; }
    sleep 2
  done
  die "launchctl could not load $2. Try: ${4:-} launchctl bootstrap $1 $2"
}

find_uv() {
  if command -v uv >/dev/null 2>&1; then command -v uv
  elif [[ -x "$HOME/.local/bin/uv" ]]; then printf '%s\n' "$HOME/.local/bin/uv"
  else return 1; fi
}

# config_tool ACTION [ARGS]: reads and rewrites the server TOML config. Never prints a token, except the `token` action.
config_tool() {
  "$UV" run --quiet --project "$REPO" python - "$CONFIG" "$@" <<'PY'
import json, os, re, secrets, sys, tomllib
from pathlib import Path

path, action, args = Path(sys.argv[1]), sys.argv[2], sys.argv[3:]


def fail(message):
    print(message, file=sys.stderr)
    sys.exit(2)


def load():
    return tomllib.loads(path.read_text()) if path.exists() else {}


def value(item):
    if isinstance(item, bool):
        return "true" if item else "false"
    if isinstance(item, int):
        return str(item)
    if isinstance(item, list):
        return "[" + ", ".join(value(entry) for entry in item) + "]"
    return json.dumps(item, ensure_ascii=False)


def save(data):
    lines = ["# Written by deploy/wizard.sh, which keeps every value on a re-run. Keep it private: mode 0600.", ""]
    tables = [("server", data["server"])]
    if "access" in data:
        tables.append(("access", data["access"]))
    for kind in ("printers", "clients"):
        tables += [(f"{kind}.{key}", table) for key, table in data.get(kind, {}).items()]
    for name, table in tables:
        lines += [f"[{name}]", *(f"{key} = {value(item)}" for key, item in table.items()), ""]
    temp = path.with_name(path.name + ".tmp")
    with os.fdopen(os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), "w") as file:
        file.write("\n".join(lines))
    os.chmod(temp, 0o600)
    os.replace(temp, path)


data = load()
if action == "init":
    if data:
        os.chmod(path, 0o600)
        print("kept the existing config")
    else:
        save({"server": {"host": "127.0.0.1", "port": 8787, "database": "data/print-server.db",
                         "admin_token": secrets.token_urlsafe(32)}})
        print("created the config with a new admin token")
elif action == "printers":
    for key, table in data.get("printers", {}).items():
        print(f"{key}\t{table.get('name', '')}\t{'public' if table.get('public') else 'private'}")
elif action == "add-printer":
    key, name, place, public = args
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", key):
        fail("The id must be lowercase letters, digits and single hyphens, e.g. home or office-desk.")
    if key in data.get("printers", {}):
        fail(f"Printer {key} already exists.")
    if not name.strip() or not place.strip():
        fail("The name and the place must not be empty.")
    data.setdefault("printers", {})[key] = {"name": name, "place": place,
                                            "token": secrets.token_urlsafe(32), "public": public == "yes"}
    save(data)
elif action == "set-access":
    team_domain, audience, emails = args
    access = data.setdefault("access", {})
    access.update(team_domain=team_domain, audience=audience)
    access.setdefault("web_rate_limit", 10)
    access["admin_emails"] = [email.strip().lower() for email in emails.split(",") if email.strip()]
    save(data)
elif action == "access":
    access = data.get("access", {})
    print(f"TEAM_DOMAIN={access.get('team_domain', '')}")
    print(f"ACCESS_AUD={access.get('audience', '')}")
    print(f"ADMIN_EMAILS={','.join(access.get('admin_emails', []))}")
elif action == "token":
    print(data["printers"][args[0]]["token"])
elif action == "admin-token":
    destination = Path(args[0])
    with os.fdopen(os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), "w") as file:
        file.write(data["server"]["admin_token"] + "\n")
    os.chmod(destination, 0o600)
elif action == "port":
    print(data["server"]["port"])
elif action == "validate":
    sys.path.insert(0, os.path.join(os.environ["REPO"], "src"))
    from server_config import ConfigError, load_config
    try:
        load_config(path)
    except ConfigError as error:
        fail(str(error))
else:
    fail(f"unknown action {action}")
PY
}

restart_server() {
  if [[ "$OS" == Darwin ]]; then sudo launchctl kickstart -k "system/$SERVER_LABEL"
  else sudo systemctl restart print-server.service; fi
}

show_server_log() {
  warn "last lines of the server log:"
  if [[ "$OS" == Darwin ]]; then tail -n 20 "$LOG_DIR/server.log" 2>/dev/null || true
  else sudo journalctl -u print-server.service -n 20 --no-pager || true; fi
}

wait_for_server() {
  if wait_for_status "http://127.0.0.1:$PORT/api/me" 401 30; then
    ok "the server answers on http://127.0.0.1:$PORT"
  else
    show_server_log
    die "The server did not answer on port $PORT (last HTTP status: ${LAST_STATUS:-none})."
  fi
}

# ── Stages shared by both roles ───────────────────────────────────────────

stage_tools() {
  stage "Tools and code"
  if [[ ! -f "$REPO/src/scripts/print_server.py" ]]; then
    die "Run this wizard from a clone of the repo: git clone https://github.com/felipemoran/daily-printer.git"
  fi
  ok "repo at $REPO"
  UV=$(find_uv || true)
  if [[ -z "$UV" ]]; then
    say "uv runs the Python code and installs its dependencies."
    if confirm "Install uv with its official installer (curl -LsSf https://astral.sh/uv/install.sh | sh)?"; then
      curl -LsSf https://astral.sh/uv/install.sh | sh
      UV=$(find_uv || true)
    fi
    [[ -n "$UV" ]] || die "uv is missing. Install it (https://docs.astral.sh/uv/getting-started/installation/), then re-run."
  fi
  ok "uv at $UV"
  step "Installing the Python dependencies (uv sync)"
  (cd "$REPO" && "$UV" sync --quiet)
  ok "Python dependencies installed"
}

# ── Server role ───────────────────────────────────────────────────────────

stage_server_build() {
  stage "Receipt renderer"
  say "The server renders receipts with a small web app and Chromium."
  command -v npm >/dev/null 2>&1 || die "npm is missing. Install Node.js (macOS: brew install node; Linux: https://nodejs.org), then re-run."
  step "Building the receipt app (npm install, npm run build)"
  (cd "$REPO/web" && npm install --silent && npm run build --silent)
  [[ -f "$REPO/web/dist/index.html" ]] || die "The build did not produce web/dist/index.html."
  ok "receipt app built"
  step "Installing Playwright's Chromium"
  if [[ "$OS" == Linux ]]; then
    note "On Linux this also installs Chromium's system libraries, so it asks for your password."
    (cd "$REPO" && "$UV" run playwright install --with-deps chromium)
  else
    (cd "$REPO" && "$UV" run playwright install chromium)
  fi
  ok "Chromium installed"
}

add_printer() {
  local public=no
  ask PRINTER_ID "Printer id (lowercase, e.g. home):"
  ask PRINTER_NAME "Name shown to senders (e.g. Home):"
  ask PRINTER_PLACE "Where it stands (e.g. Home office):"
  confirm "May web senders (friends, colleagues) print on it?" && public=yes
  if config_tool add-printer "$PRINTER_ID" "$PRINTER_NAME" "$PRINTER_PLACE" "$public"; then
    ok "added printer $PRINTER_ID with a new token"
  fi
}

stage_server_config() {
  stage "Server config and tokens"
  say "The config holds the admin token, the printers and their tokens: $CONFIG"
  mkdir -p "$LOG_DIR"
  chmod 700 "$STATE_DIR"
  local result; result=$(config_tool init)
  ok "$result"
  local printers; printers=$(config_tool printers)
  if [[ -z "$printers" ]]; then
    say "Add each receipt printer. You can add more later by re-running this wizard."
    add_printer
  else
    say "Printers:"
    printf '%s\n' "$printers" | while IFS=$'\t' read -r id name visibility; do note "  $id  $name  ($visibility)"; done
  fi
  while confirm "Add another printer?"; do add_printer; done
  config_tool validate || die "The config is not valid; fix $CONFIG and re-run."
  config_tool admin-token "$STATE_DIR/admin-token"
  ok "config valid, mode 0600"
  ok "admin token for printctl in $STATE_DIR/admin-token (mode 0600)"
  PORT=$(config_tool port)
}

stage_server_service() {
  stage "Server service"
  say "The server starts at boot and restarts when it stops. Installing it asks for your password (sudo)."
  if [[ "$OS" == Darwin ]]; then
    local plist=/Library/LaunchDaemons/$SERVER_LABEL.plist
    install_rendered "$REPO/deploy/launchd/$SERVER_LABEL.plist" "$plist" 600 sudo
    launchd_load system "$plist" "$SERVER_LABEL" sudo
  else
    install_rendered "$REPO/deploy/systemd/print-server.service" /etc/systemd/system/print-server.service 644 sudo
    sudo systemctl daemon-reload
    sudo systemctl enable --quiet print-server.service
    sudo systemctl restart print-server.service
    ok "print-server.service enabled and started"
  fi
  wait_for_server
}

tunnel_id() {
  cloudflared tunnel list 2>/dev/null \
    | awk -v name="$1" '{ for (i = 1; i <= NF; i++) if ($i == name) print }' \
    | grep -Eo '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | head -n 1 || true
}

stage_tunnel() {
  stage "Cloudflare Tunnel"
  say "The tunnel gives the server public hostnames without opening router ports."
  if ! command -v cloudflared >/dev/null 2>&1; then
    if [[ "$OS" == Darwin ]] && command -v brew >/dev/null 2>&1 && confirm "Install cloudflared with Homebrew (brew install cloudflared)?"; then
      brew install cloudflared
    else
      open_url "$DOCS/connections/connect-networks/downloads/"
      step "Install cloudflared for this system, then come back."
      pause
    fi
    command -v cloudflared >/dev/null 2>&1 || die "cloudflared is missing. Install it, then re-run."
  fi
  ok "cloudflared at $(command -v cloudflared)"
  if [[ -f "$HOME/.cloudflared/cert.pem" ]]; then
    ok "already logged in to Cloudflare"
  else
    step "A browser opens. Log in to Cloudflare and select the domain (zone) for the print hostnames."
    cloudflared tunnel login
    [[ -f "$HOME/.cloudflared/cert.pem" ]] || die "The login did not write ~/.cloudflared/cert.pem."
  fi
  ask TUNNEL_NAME "Tunnel name [Enter for daily-printer]:"
  TUNNEL_NAME=${TUNNEL_NAME:-daily-printer}
  write_env TUNNEL_NAME "$TUNNEL_NAME"
  TUNNEL_ID=$(tunnel_id "$TUNNEL_NAME")
  if [[ -z "$TUNNEL_ID" ]]; then
    cloudflared tunnel create "$TUNNEL_NAME"
    TUNNEL_ID=$(tunnel_id "$TUNNEL_NAME")
  else
    ok "tunnel $TUNNEL_NAME exists"
  fi
  if [[ -z "$TUNNEL_ID" ]]; then
    note "Run 'cloudflared tunnel list' in another terminal; the ID is the long value on the $TUNNEL_NAME line."
    ask TUNNEL_ID "Tunnel ID:"
  fi
  [[ -f "$HOME/.cloudflared/$TUNNEL_ID.json" ]] \
    || die "No credentials file ~/.cloudflared/$TUNNEL_ID.json. It is written only on the machine that created the tunnel: copy it here, or re-run with a new tunnel name."
  write_env TUNNEL_ID "$TUNNEL_ID"
  ok "tunnel $TUNNEL_NAME ($TUNNEL_ID)"
}

stage_hostnames() {
  stage "Public hostnames"
  say "Two hostnames point at this server: one for senders (behind a login), one for devices."
  while :; do
    ask SENDER_HOST "Hostname for senders, the web form (e.g. print.example.com):"
    ask DEVICE_HOST "Hostname for devices (e.g. print-device.example.com):"
    if [[ ! "$SENDER_HOST" =~ $HOSTNAME_PATTERN || ! "$DEVICE_HOST" =~ $HOSTNAME_PATTERN ]]; then
      warn "Enter bare hostnames, without https:// or a path."
    elif [[ "$SENDER_HOST" == "$DEVICE_HOST" ]]; then
      warn "The two hostnames must differ: only the sender hostname gets a login page."
    else
      break
    fi
  done
  write_env SENDER_HOST "$SENDER_HOST"
  write_env DEVICE_HOST "$DEVICE_HOST"
  local host
  for host in "$SENDER_HOST" "$DEVICE_HOST"; do
    if cloudflared tunnel route dns "$TUNNEL_ID" "$host"; then
      ok "DNS record for $host"
    else
      warn "cloudflared could not create the DNS record for $host."
      note "If the message says the record already exists and it points to this tunnel, continue."
      confirm "Continue?" || die "Fix the DNS record in the Cloudflare dashboard, then re-run."
    fi
  done
}

stage_tunnel_service() {
  stage "Tunnel service"
  say "cloudflared runs as a system service and reads $CLOUDFLARED_CONFIG. This asks for your password (sudo)."
  sudo mkdir -p /etc/cloudflared
  sudo install -m 600 "$HOME/.cloudflared/$TUNNEL_ID.json" "/etc/cloudflared/$TUNNEL_ID.json"
  install_rendered "$REPO/deploy/cloudflared/config.example.yml" "$CLOUDFLARED_CONFIG" 644 sudo
  cloudflared --config "$CLOUDFLARED_CONFIG" tunnel ingress validate || die "cloudflared refused $CLOUDFLARED_CONFIG."
  ok "ingress rules valid"
  if [[ "$OS" == Darwin ]]; then
    if sudo launchctl print "system/$CLOUDFLARED_LABEL" >/dev/null 2>&1; then
      sudo launchctl kickstart -k "system/$CLOUDFLARED_LABEL"
      ok "restarted the cloudflared service"
    else
      sudo cloudflared service install
      ok "installed the cloudflared service"
    fi
  else
    if systemctl cat cloudflared.service >/dev/null 2>&1; then
      sudo systemctl restart cloudflared.service
      ok "restarted the cloudflared service"
    else
      sudo cloudflared --config "$CLOUDFLARED_CONFIG" service install
      sudo systemctl start cloudflared.service
      ok "installed the cloudflared service"
    fi
  fi
  step "Checking the device hostname through the tunnel (new DNS records can take a minute)"
  wait_for_status "https://$DEVICE_HOST/device" 401 90 \
    || note "530 or 1033: the tunnel is not connected. 502: cloudflared cannot reach the server on port $PORT."
  check_device_host
}

# check_device_host: dies unless the device hostname reaches the server for /device only, with no Access login.
check_device_host() {
  local path expected code
  for path in /device:401 /:404 /api/me:404; do
    expected=${path#*:}
    path=${path%%:*}
    code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 "https://$DEVICE_HOST$path" || true)
    if [[ "$code" != "$expected" ]]; then
      case "$code" in
        3*|403) die "https://$DEVICE_HOST$path answered $code: Cloudflare Access covers the device hostname. Remove $DEVICE_HOST from every Access application (look for a wildcard), then re-run." ;;
        *) die "https://$DEVICE_HOST$path answered $code, not $expected. Check $CLOUDFLARED_CONFIG and the cloudflared service, then re-run." ;;
      esac
    fi
  done
  ok "https://$DEVICE_HOST serves /device only, with no Access login"
}

# access_protects_sender: true when the sender hostname redirects to this team's Access login.
access_protects_sender() {
  ACCESS_ANSWER=$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' --max-time 10 "https://$SENDER_HOST/" || true)
  [[ "$ACCESS_ANSWER" == 3??" https://$TEAM_DOMAIN/"* ]]
}

stage_access() {
  stage "Cloudflare Access for $SENDER_HOST"
  say "Access puts a login page in front of the sender hostname. Senders get a one-time PIN by email."
  warn "Protect only $SENDER_HOST. Devices cannot log in to Access, so $DEVICE_HOST must stay outside it."
  open_url "https://dash.cloudflare.com/"
  step "Zero Trust > Integrations > Identity providers. If One-time PIN is not listed:"
  note "  Add new identity provider > One-time PIN."
  step "Zero Trust > Access controls > Applications > Create new application > Self-hosted and private."
  step "Add public hostname: the subdomain and domain of $SENDER_HOST. No wildcard."
  step "Access policies: create a policy with action Allow and two Include rules:"
  note "  Emails: the address of each friend who may send prints."
  note "  Emails ending in: @<your office domain>."
  note "  Include rules are OR: a sender needs to match one of them."
  step "Identity providers: select One-time PIN. Then select Create."
  step "Keep Rocket Loader and automatic Web Analytics injection off for $SENDER_HOST:"
  note "  The web form allows only its own script hash (CSP): both would be blocked, and Rocket Loader stops the page script."
  note "  Speed > Settings > Content Optimization > Rocket Loader: off, or off for $SENDER_HOST with a configuration rule."
  note "  Web analytics: if the site is listed, Manage site > Disable (or Enable with JS Snippet installation)."
  pause "Press Enter when the application exists and both are off."
  local current; current=$(mktemp)
  config_tool access > "$current"
  step "Applications > Configure (on the new application) > Additional settings: copy the Application Audience (AUD) Tag."
  ENV_FILE=$current ask ACCESS_AUD "AUD tag:"
  step "Zero Trust > Settings: copy the team domain, <team>.cloudflareaccess.com."
  while :; do
    ENV_FILE=$current ask TEAM_DOMAIN "Team domain:"
    TEAM_DOMAIN=${TEAM_DOMAIN#https://}
    TEAM_DOMAIN=${TEAM_DOMAIN%/}
    [[ "$TEAM_DOMAIN" =~ $HOSTNAME_PATTERN ]] && break
    warn "Enter a hostname such as myteam.cloudflareaccess.com."
  done
  ENV_FILE=$current ask ADMIN_EMAILS "Logins that may use the admin web pages, comma-separated (- for none):"
  if [[ "$ADMIN_EMAILS" == "-" ]]; then ADMIN_EMAILS=""; fi
  rm -f "$current"
  config_tool set-access "$TEAM_DOMAIN" "$ACCESS_AUD" "$ADMIN_EMAILS"
  config_tool validate || die "The config is not valid; fix $CONFIG and re-run."
  ok "Access settings written to the config"
  restart_server
  wait_for_server
  until access_protects_sender; do
    warn "https://$SENDER_HOST/ answered '$ACCESS_ANSWER', not a redirect to the Access login."
    note "Check that an Access application covers exactly $SENDER_HOST and has an Allow policy."
    confirm "Re-check?" || die "Cloudflare Access does not protect https://$SENDER_HOST/. Fix the application in Zero Trust > Access controls > Applications, then re-run deploy/wizard.sh server."
  done
  ok "https://$SENDER_HOST/ sends visitors to the Access login"
  check_device_host
}

stage_tokens() {
  stage "Printer tokens"
  say "Each printer machine runs the device service. On each one:"
  step "Clone the repo: git clone https://github.com/felipemoran/daily-printer.git"
  step "Run: deploy/wizard.sh device"
  note "It asks for the device hostname and the printer's token. A printer on this machine needs it too."
  local id
  for id in $(config_tool printers | cut -f1); do
    if confirm "Show the token of printer '$id' now, to paste into its device?"; then
      printf '\n    %s%s%s\n\n' "$BOLD" "$(config_tool token "$id")" "$RESET"
      pause "Press Enter after you copy it. The screen and its scrollback clear."
      _clear
      if [[ -t 1 ]]; then printf '\033[3J'; fi
    fi
  done
}

# ── Device role ───────────────────────────────────────────────────────────

stage_device_libusb() {
  if [[ "$OS" == Darwin ]]; then
    if compgen -G "/opt/homebrew/lib/libusb-1.0*.dylib" >/dev/null || compgen -G "/usr/local/lib/libusb-1.0*.dylib" >/dev/null; then
      ok "libusb installed"
    else
      confirm "The USB printer needs libusb. Install it now (brew install libusb)?" \
        || die "libusb is missing, so every print would fail. Install it (brew install libusb), then re-run."
      command -v brew >/dev/null 2>&1 || die "Homebrew is missing. Install it (https://brew.sh), run brew install libusb, then re-run."
      brew install libusb
    fi
    note "If System Settings > Printers & Scanners lists the receipt printer, remove it: macOS may claim the USB device."
  elif ldconfig -p 2>/dev/null | grep -q 'libusb-1.0'; then
    ok "libusb installed"
  else
    confirm "The USB printer needs libusb. Install it now (sudo apt-get install -y libusb-1.0-0)?" \
      || die "libusb is missing, so every print would fail. Install it (sudo apt-get install libusb-1.0-0), then re-run."
    command -v apt-get >/dev/null 2>&1 || die "No apt-get here. Install libusb-1.0 with this system's package manager, then re-run."
    sudo apt-get install -y libusb-1.0-0
    ldconfig -p 2>/dev/null | grep -q 'libusb-1.0' || die "libusb is still missing after the install."
  fi
}

stage_device_token() {
  stage "Server and printer token"
  stage_device_libusb
  while :; do
    ask DEVICE_HOST "Device hostname of the print server (e.g. print-device.example.com):"
    [[ "$DEVICE_HOST" =~ $HOSTNAME_PATTERN ]] && break
    warn "Enter a bare hostname, without wss:// or a path."
  done
  write_env DEVICE_HOST "$DEVICE_HOST"
  SERVER_URL="wss://$DEVICE_HOST/device"
  mkdir -p "$LOG_DIR"
  chmod 700 "$STATE_DIR"
  if [[ -s "$TOKEN_FILE" ]] && ! confirm "A printer token is saved in $TOKEN_FILE. Replace it?"; then
    ok "kept the saved token"
  else
    note "On the server machine, 'deploy/wizard.sh tokens' shows each printer's token."
    while :; do
      ask_secret PRINTER_TOKEN "Paste the printer token (hidden):"
      (( ${#PRINTER_TOKEN} >= 24 )) && break
      warn "A printer token has at least 24 characters. Copy the whole token."
    done
    (umask 077; printf '%s\n' "$PRINTER_TOKEN" > "$TOKEN_FILE")
    chmod 600 "$TOKEN_FILE"
    PRINTER_TOKEN=""
    ok "token saved in $TOKEN_FILE (mode 0600)"
  fi
  local header code
  header=$(mktemp)
  (umask 077; printf 'Authorization: Bearer %s\n' "$(head -n 1 "$TOKEN_FILE")" > "$header")
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 -H "@$header" "https://$DEVICE_HOST/device" || true)
  rm -f "$header"
  case "$code" in
    400) ok "the server accepted the token" ;;
    401) die "The server refused this token. Re-run and paste the token of this printer." ;;
    3*|403) die "https://$DEVICE_HOST/device answered $code: Cloudflare Access covers the device hostname. Remove it from every Access application, then re-run." ;;
    000) die "https://$DEVICE_HOST is not reachable from here. Check the hostname and the tunnel on the server, then re-run." ;;
    *) die "https://$DEVICE_HOST/device answered $code, not 400. Check the tunnel on the server, then re-run." ;;
  esac
}

stage_device_service() {
  stage "Device service"
  local since log=""
  if [[ "$OS" == Darwin ]]; then
    say "The device runs as your user while you are logged in. It needs no admin rights."
    log="$LOG_DIR/device.log"
    launchctl bootout "gui/$(id -u)/$DEVICE_LABEL" 2>/dev/null || true
    since=$( (wc -l < "$log") 2>/dev/null || echo 0)
    mkdir -p "$HOME/Library/LaunchAgents"
    install_rendered "$REPO/deploy/launchd/$DEVICE_LABEL.plist" "$HOME/Library/LaunchAgents/$DEVICE_LABEL.plist" 600
    launchd_load "gui/$(id -u)" "$HOME/Library/LaunchAgents/$DEVICE_LABEL.plist" "$DEVICE_LABEL"
  else
    say "The device starts at boot. Installing it asks for your password (sudo)."
    printf 'SUBSYSTEM=="usb", ATTR{idVendor}=="6868", ATTR{idProduct}=="0200", OWNER="%s"\n' "$SERVICE_USER" \
      | sudo tee /etc/udev/rules.d/60-daily-printer.rules >/dev/null
    sudo udevadm control --reload
    sudo udevadm trigger
    ok "udev rule: $SERVICE_USER may open the receipt printer"
    install_rendered "$REPO/deploy/systemd/print-device.service" /etc/systemd/system/print-device.service 644 sudo
    sudo systemctl daemon-reload
    sudo systemctl enable --quiet print-device.service
    sudo systemctl stop print-device.service
    since=$(date +%s)
    sudo systemctl start print-device.service
    ok "print-device.service enabled and started"
  fi
  step "Waiting for the device to connect"
  until device_connected "$since" "$log"; do
    warn "The device did not report a connection within 30 s. Last log lines:"
    printf '%s\n' "$DEVICE_LOG" | tail -n 10
    confirm "Re-check?" || die "The device is not connected. Fix the cause in the log above, then re-run deploy/wizard.sh device."
  done
  ok "the device is connected to $SERVER_URL"
}

# device_connected SINCE LOG: true once the device logs a connection after SINCE: a line count of LOG (macOS) or an epoch second (Linux).
device_connected() {
  local deadline=$((SECONDS + 30))
  DEVICE_LOG=""
  while (( SECONDS < deadline )); do
    if [[ "$OS" == Darwin ]]; then DEVICE_LOG=$(tail -n "+$(($1 + 1))" "$2" 2>/dev/null || true)
    else DEVICE_LOG=$(sudo journalctl -u print-device.service --since "@$1" --no-pager -o cat 2>/dev/null || true); fi
    [[ "$DEVICE_LOG" == *"connected to"* ]] && return 0
    sleep 2
  done
  return 1
}

# ── Main ──────────────────────────────────────────────────────────────────

case "$OS" in Darwin|Linux) ;; *) die "This wizard supports macOS and Linux, not $OS." ;; esac
(( EUID != 0 )) || die "Run as your user; the wizard calls sudo itself."
if [[ "$REPO$HOME_DIR" =~ [[:space:]] ]]; then die "The repo path and the home folder must not contain spaces: the service files cannot quote them."; fi
ROLE=${1:-}
case "$ROLE" in
  server|tokens)
    STATE_DIR=$HOME_DIR/print-server
    CONFIG=$STATE_DIR/config.toml
    LOG_DIR=$STATE_DIR/logs
    ;;
  device)
    STATE_DIR=$HOME_DIR/print-device
    TOKEN_FILE=$STATE_DIR/token
    LOG_DIR=$STATE_DIR/logs
    ;;
  -h|--help) usage; exit 0 ;;
  *) usage >&2; exit 2 ;;
esac
mkdir -p "$STATE_DIR"
ENV_FILE=$STATE_DIR/wizard.env

case "$ROLE" in
  server)
    TOTAL_STAGES=9
    banner "Print server setup"
    stage_tools
    stage_server_build
    stage_server_config
    stage_server_service
    stage_tunnel
    stage_hostnames
    stage_tunnel_service
    stage_access
    stage_tokens
    finish
    note "printctl reads the admin token with --token-file $STATE_DIR/admin-token."
    note "Senders open https://$SENDER_HOST/. Logs: $([[ "$OS" == Darwin ]] && echo "$LOG_DIR/server.log" || echo "journalctl -u print-server")"
    ;;
  tokens)
    [[ -f "$CONFIG" ]] || die "No config at $CONFIG. Run deploy/wizard.sh server first."
    UV=$(find_uv) || die "uv is missing. Run deploy/wizard.sh server first."
    TOTAL_STAGES=1
    stage_tokens
    ;;
  device)
    TOTAL_STAGES=3
    banner "Printer device setup"
    stage_tools
    stage_device_token
    stage_device_service
    finish
    note "Logs: $([[ "$OS" == Darwin ]] && echo "$LOG_DIR/device.log" || echo "journalctl -u print-device")"
    ;;
esac
